ype="text" x-model="form.whatsapp" class="w-full border border-gray-300 rounded-xl px-3 py-2.5 text-sm focus:ring-2 focus:ring-primary/30 focus:border-primary outline-none"></div><div><label class="block text-sm font-medium text-gray-700 mb-1.5">Email</label><input type="email" x-model="form.email" class="w-full border border-gray-300 rounded-xl px-3 py-2.5 text-sm focus:ring-2 focus:ring-primary/30 focus:border-primary outline-none"></div><div><label class="block text-sm font-medium text-gray-700 mb-1.5">Shop Type</label><select x-model="form.shop_type" class="w-full border border-gray-300 rounded-xl px-3 py-2.5 text-sm focus:ring-2 focus:ring-primary/30 focus:border-primary outline-none"><option value="retail">Retail</option><option value="wholesale">Wholesale</option><option value="supermarket">Supermarket</option><option value="online">Online</option><option value="other">Other</option></select></div><div><label class="block text-sm font-medium text-gray-700 mb-1.5">Salesman</label><select x-model="form.salesman_id" class="w-full border border-gray-300 rounded-xl px-3 py-2.5 text-sm focus:ring-2 focus:ring-primary/30 focus:border-primary outline-none"><option value="">Select salesman</option><template x-for="s in salesmen" :key="s.id"><option :value="s.id" x-text="s.name"></option></template></select></div><div><label class="block text-sm font-medium text-gray-700 mb-1.5">City</label><input type="text" x-model="form.city" class="w-full border border-gray-300 rounded-xl px-3 py-2.5 text-sm focus:ring-2 focus:ring-primary/30 focus:border-primary outline-none"></div><div><label class="block text-sm font-medium text-gray-700 mb-1.5">Area</label><input type="text" x-model="form.area" class="w-full border border-gray-300 rounded-xl px-3 py-2.5 text-sm focus:ring-2 focus:ring-primary/30 focus:border-primary outline-none"></div><div><label class="block text-sm font-medium text-gray-700 mb-1.5">Credit Limit</label><input type="number" min="0" step="0.01" x-model="form.cr