@push('scripts')<script>function shopData(){return{pager:{loading:true,items:[],currentPage:1,perPage:10,total:0,totalPages:1,get visiblePages(){return[]},fetchPage(){return Promise.resolve(false)},setSearch(){},refresh(){return Promise.resolve(false)},goToPage(){},changePerPage(){}},salesmen:[],search:'',saving:false,modalOpen:false,deleteModalOpen:false,editId:null,deleteTarget:null,form:{name:'',owner_name:'',email:'',phone:'',whatsapp:'',address:'',city:'',area:'',shop_type:'retail',salesman_id:'',credit_limit:0},errors:{},async init(){try{this.pager=Alpine.store('pager').create({endpoint:'/api/v1/shop',perPage:10})}catch(e){console.error('Pager create failed:',e);this.pager.loading=false;return}this.fetchDependencies();this.pager.fetchPage()},doSearch(){try{this.pager.setSearch({search:this.search||undefined})}catch(e){this.search=''}},async fetchDependencies(){try{var d=await Alpine.store('api').get('/api/v1/salesman',{per_page:200});if(d&&d.status)this.salesmen=Array.isArray(d.data)?d.data:(d.data?.data||[])}catch(e){console.error('Failed to load salesmen:',e)}},openAddModal(){this.editId=null;this.errors={};this.form={name:'',owner_name:'',email:'',phone:'',whatsapp:'',address:'',city:'',area:'',shop_type:'retail',salesman_id:'',credit_limit:0};if(this.salesmen.length===0)this.fetchDependencies();this.modalOpen=true},openEditModal(s){this.editId=s.id;this.errors={};this.form={name:s.name||'',owner_name:s.owner_name||'',email:s.email||'',phone:s.phone||'',whatsapp:s.whatsapp||'',address:s.address||'',city:s.city||'',area:s.area||'',shop_type:s.shop_type||'retail',salesman_id:s.salesman_id||'',credit_limit:s.credit_limit||0};if(this.salesmen.length===0)this.fetchDependencies();this.modalOpen=true},confirmDelete(s){this.deleteTarget=s;this.deleteModalOpen=true},closeModal(){this.modalOpen=false;this.editId=null;this.errors={}},async saveItem(){this.errors={};if(!this.form.name){this.errors.name='Name is required';return}this.saving=true;try{this.editId?await Alpine.store('api').put('/api/v1/shop/'+this.editId,this.form):await Alpine.store('api').post('/api/v1/shop',this.form);this.closeModal();Alpine.store('toast').success(this.editId?'Shop updated':'Shop created');this.pager.refresh()}catch(e){if(e.errors)this.errors=e.errors;else Alpine.store('toast').error(e.message||'Save failed')}finally{this.saving=false}},async deleteItem(){if(!this.deleteTarget)return;this.saving=true;try{await Alpine.store('api').del('/api/v1/shop/'+this.deleteTarget.id);this.deleteModalOpen=false;this.deleteTarget=null;Alpine.store('toast').success('Shop deleted');this.pager.refresh()}catch(e){Alpine.store('toast').error(e.message||'Delete failed')}finally{this.saving=false}}}}</script>@endpush
